    render(<OnBudgetTransfersToggle includeOnBudgetTransfers={false} onToggle={mockToggle} />);

    const toggle = screen.getByRole('switch');
    fireEvent.click(toggle);

    expect(mockToggle).toHaveBeenCalledTimes(1);
